import re,unicodedata
def n(s):
    s=unicodedata.normalize("NFD",s); s="".join(c for c in s if not unicodedata.combining(c)).lower()
    s=s.replace("(zone naturelle)","zone naturelle").replace("z.a.","za ").replace("zone d'activites","zone activite").replace("st-","saint-").replace("st ","saint ").replace("mitterand","mitterrand")
    return re.sub(r"[^a-z0-9]","",s)
ra3=json.load(open("ra3.json")); d3=json.load(open("dpe3.json")); rc={"angers":226,"caen":234,"orleans":209}
for k in ra3:
    txt=open(f"iris_{k}.txt").read().strip(); rn={n(a):v for a,v in ra3[k].items()}
    q={}
    for l in txt.split("\n"):
        nm=l.split("|")[0]
        if n(nm) in rn: q[nm]=rn[n(nm)]
    out[k]={"txt":txt,"dpe":d3[k],"ra":{"city":rc[k],"q":{},"fit":[0,0.229]},"q":q}
    print(k,len(q))
open("irisdata.js","w").write("const IRIS="+json.dumps(out,ensure_ascii=False)+";")
print(len(open("irisdata.js").read()))
